require('@babel/register')({presets:['@babel/preset-env']});
const luxon = require('./src/luxon.js');
const { Interval, DateTime, Duration, Settings } = luxon;

// Proposed fixed implementation
Interval.fromISO = function (text, opts) {
  const [s, e] = (text || '').split('/', 2);
  if (s && e) {
    let start, startIsValid;
    try {
      start = DateTime.fromISO(s, opts);
      startIsValid = start.isValid;
    } catch (err) {
      startIsValid = false;
    }
    let end, endIsValid;
    try {
      end = DateTime.fromISO(e, opts);
      endIsValid = end.isValid;
    } catch (err) {
      endIsValid = false;
    }
    if (startIsValid && endIsValid) {
      return Interval.fromDateTimes(start, end);
    }
    if (startIsValid) {
      const dur = Duration.fromISO(e, opts);
      if (dur.isValid) {
        return Interval.after(start, dur);
      }
    } else if (endIsValid) {
      const dur = Duration.fromISO(s, opts);
      if (dur.isValid) {
        return Interval.before(end, dur);
      }
    }
  }
  return Interval.invalid('unparsable', \`the input \"\${text}\" can't be parsed as ISO 8601\`);
};

Settings.throwOnInvalid = true;
const inputs = ['2020-01-01/2020-01-02','2020-01-01/P1Y','P1Y/2020-01-01','hello','foo/bar','2020-01-01/foo',''];
for (const i of inputs) {
  try {
    const r = Interval.fromISO(i);
    console.log(JSON.stringify(i), '=> OK valid=', r.isValid);
  } catch (err) {
    console.log(JSON.stringify(i), '=> THREW', err.constructor.name, '::', err.message);
  }
}
Settings.throwOnInvalid = false;
"

